// Synthetic manager report only. No real review/source access or provider call.
import {crossRatingAnalysis,type CrossReview,type TextFinding} from '../../supabase/functions/_shared/cross-rating-analysis'
import {AXES,type ConsultantReportData} from '../../supabase/functions/_shared/consultant-contract'
import {buildAxisDiagnostics,globalDecisionSummary,diagnosticConclusion,type CountedTopic} from '../../supabase/functions/_shared/consultant-diagnostics'
import {withManagerConclusion} from '../../supabase/functions/_shared/consultant-conclusion'
import {GOLD_TAXONOMY,type GoldTheme} from '../../supabase/functions/_shared/gold-taxonomy'
import {reputationMetrics,type ReputationReview} from '../../supabase/functions/_shared/reputation-metrics'
import {analysisInputStats} from '../../supabase/functions/_shared/analysis-text'
import {structuredContextStats} from '../../supabase/functions/_shared/structured-review-context'
export function syntheticV8(language:'fr'|'vi'='fr'){
  const reviews:CrossReview[]=[{id:'unexplained',rating:5,analysis_text:'Excellent food.',review_detailed_rating:{Food:5,Service:2,Atmosphere:5}},{id:'hidden',rating:5,analysis_text:'We waited 45 minutes for our food.',review_detailed_rating:{Food:5,Service:5,Atmosphere:5}},{id:'confirmed',rating:3,analysis_text:'Food was excellent but the waiter ignored us.',review_detailed_rating:{Food:5,Service:2,Atmosphere:4}},{id:'positive',rating:5,analysis_text:'Delicious food.',review_detailed_rating:{Food:5,Service:5,Atmosphere:5}},{id:'textless',rating:5,analysis_text:'',review_detailed_rating:{Food:5},review_context:{price_per_person:'100–200 N ₫'}},{id:'mixed',rating:5,analysis_text:'The food tasted good but was cold.',review_detailed_rating:{Food:5,Atmosphere:4}}]
  const findings:TextFinding[]=[{review_id:'unexplained',theme_key:'food_quality',sentiment:'positive',evidence:'Excellent food'},{review_id:'hidden',theme_key:'wait_time',sentiment:'negative',evidence:'waited 45 minutes'},{review_id:'confirmed',theme_key:'food_quality',sentiment:'positive',evidence:'Food was excellent'},{review_id:'confirmed',theme_key:'attentiveness',sentiment:'negative',evidence:'ignored us'},{review_id:'positive',theme_key:'food_quality',sentiment:'positive',evidence:'Delicious food'},{review_id:'mixed',theme_key:'food_quality',sentiment:'positive',evidence:'good'},{review_id:'mixed',theme_key:'temperature',sentiment:'negative',evidence:'cold'}]
  const inputs:ReputationReview[]=reviews.map(r=>({...r,original_text:r.analysis_text??'',original_language:'en',analysis_language:'en',analysis_source:r.analysis_text?'original_en':'textless',text:null,published_at:null,historical_import:true,has_negative_feedback:null,status:'new',review_detailed_rating:r.review_detailed_rating as Record<string,unknown>,review_context:r.review_context as Record<string,unknown>??null}))
  const base=reputationMetrics(inputs,inputs.length),groups=new Map<string,{theme:GoldTheme;sentiment:'positive'|'negative';ids:string[]}>()
  for(const f of findings){const key=f.theme_key+':'+f.sentiment,g=groups.get(key)??{theme:f.theme_key as GoldTheme,sentiment:f.sentiment,ids:[]};if(!g.ids.includes(f.review_id))g.ids.push(f.review_id);groups.set(key,g)}
  const topics:CountedTopic[]=[...groups.entries()].map(([key,g])=>({key,axis:GOLD_TAXONOMY[g.theme].axis,sentiment:g.sentiment,mentions:g.ids.length,review_ids:g.ids,label:GOLD_TAXONOMY[g.theme][language]})),axis_diagnostics=buildAxisDiagnostics(inputs.length,topics,base,language),decision_summary=globalDecisionSummary(axis_diagnostics,language)
  const aspects=[...groups.values()].map(g=>({theme_key:g.theme,axis:GOLD_TAXONOMY[g.theme].axis,sentiment:g.sentiment,label:GOLD_TAXONOMY[g.theme][language],mentions:g.ids.length,explanation:GOLD_TAXONOMY[g.theme][language]}))
  const report:ConsultantReportData={version:8,language,total:inputs.length,positive:base.positive_reviews_count,negative:base.negative_reviews_count,sample_average_rating:base.sample_average_rating,axis_diagnostics,decision_summary,axes:AXES.map(key=>({key,positive:new Set(topics.filter(t=>t.axis===key&&t.sentiment==='positive').flatMap(t=>t.review_ids)).size,negative:new Set(topics.filter(t=>t.axis===key&&t.sentiment==='negative').flatMap(t=>t.review_ids)).size,summary:axis_diagnostics[key].summary,recommendation:language==='fr'?'S’appuyer sur les constats documentés.':'Dựa trên các nhận xét đã được ghi nhận.'})),positive_aspects:aspects.filter(a=>a.sentiment==='positive'),negative_aspects:aspects.filter(a=>a.sentiment==='negative'),conclusion:diagnosticConclusion(decision_summary,base.positive_reviews_count,base.negative_reviews_count,language),structured_context_stats:structuredContextStats(inputs),analysis_input_stats:analysisInputStats(inputs),cross_rating_analysis:crossRatingAnalysis(inputs,findings)}
  return withManagerConclusion(report)
}
